package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevDept string = "   "
var WsRegHours decimal.Decimal = decimal.NewFromInt(0)
var WsOtHours decimal.Decimal = decimal.NewFromInt(0)
var WsGross decimal.Decimal = decimal.NewFromInt(0)
var WsDeptTotal decimal.Decimal = decimal.NewFromInt(0)
var WsDeptCount int64 = 0
var WsGrandTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrandCount int64 = 0
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var EmpRecState EmpRec

var empFile *os.File
var empReader *bufio.Reader
var inputDone bool

func formatNumericEdited(val decimal.Decimal, pic string) string {
	// Determine integer digits count and decimal places from pic
	// pic contains Z,9,',','.'
	dotIdx := strings.Index(pic, ".")
	var intPic, decPic string
	decPlaces := 0
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		decPic = pic[dotIdx+1:]
		decPlaces = len(decPic)
	} else {
		intPic = pic
	}
	// Count integer digit positions (Z and 9)
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	// Round to decPlaces (COBOL MOVE does rounding? For edited fields, assume rounded)
	// But gross values already rounded appropriately. Use Round.
	rounded := val.Round(int32(decPlaces))
	// Handle negative? Not needed here (all positive)
	neg := rounded.IsNegative()
	if neg {
		rounded = rounded.Neg()
	}
	// Split integer and fractional
	s := rounded.StringFixed(int32(decPlaces)) // includes dot if decPlaces>0
	var intPartStr, fracPartStr string
	if decPlaces > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPartStr = parts[0]
		fracPartStr = parts[1]
	} else {
		intPartStr = s
	}
	// Truncate high-order digits if overflow
	if len(intPartStr) > intDigits {
		intPartStr = intPartStr[len(intPartStr)-intDigits:]
	}
	// Pad int part with leading zeros to intDigits length
	if len(intPartStr) < intDigits {
		intPartStr = strings.Repeat("0", intDigits-len(intPartStr)) + intPartStr
	}
	// Now build edited integer part respecting pic
	// intPic includes commas and digit placeholders
	resultInt := make([]byte, len(intPic))
	// Map digit positions
	// Fill from rightmost
	digitIdx := len(intPartStr) - 1
	// For Z suppression: need to know if any non-zero has been encountered
	// Z suppression replaces leading zeros with spaces, commas inside suppressed zone become spaces
	suppressing := true
	// First pass: fill digits and mark where suppression applies
	// We need to know for each placeholder whether it's suppressed
	// Iterate over intPic from right to left
	// Keep array of placeholder indices
	type placeholder struct {
		picIdx int
		char   rune
		digit  byte
	}
	var placeholders []placeholder
	for i := len(intPic) - 1; i >= 0; i-- {
		c := rune(intPic[i])
		if c == 'Z' || c == '9' {
			d := byte('0')
			if digitIdx >= 0 {
				d = intPartStr[digitIdx]
				digitIdx--
			}
			placeholders = append([]placeholder{{picIdx: i, char: c, digit: d}}, placeholders...)
		}
	}
	// Now determine suppression
	// Find last non-zero digit position among placeholders
	lastNonZero := -1
	for i, ph := range placeholders {
		if ph.digit != '0' {
			lastNonZero = i
		}
	}
	// Build resultInt
	for i := len(intPic) - 1; i >= 0; i-- {
		c := intPic[i]
		resultInt[i] = byte(c)
	}
	// Fill digits
	phIdxMap := make(map[int]int) // picIdx -> placeholder index
	for idx, ph := range placeholders {
		phIdxMap[ph.picIdx] = idx
	}
	for _, ph := range placeholders {
		idx := ph.picIdx
		isLeading := true
		if lastNonZero == -1 {
			// all zeros: only the rightmost placeholder prints 0, others suppressed if Z
			// COBOL: if value is zero, the rightmost digit prints 0, leading Zs become spaces
			if ph.picIdx == placeholders[len(placeholders)-1].picIdx {
				resultInt[idx] = '0'
			} else {
				if ph.char == 'Z' {
					resultInt[idx] = ' '
				} else {
					resultInt[idx] = ph.digit
				}
			}
		} else {
			if phIdxMap[idx] < lastNonZero {
				// leading zero zone
				if ph.char == 'Z' {
					resultInt[idx] = ' '
				} else {
					resultInt[idx] = ph.digit
				}
			} else if phIdxMap[idx] == lastNonZero {
				resultInt[idx] = ph.digit
			} else {
				resultInt[idx] = ph.digit
			}
		}
		_ = isLeading
		_ = suppressing
	}
	// Commas inside suppressed zone become spaces
	// A comma is suppressed if all placeholders to its left that are significant are suppressed (i.e., no non-zero to left of comma has been printed)
	// Simpler: if to the left of comma there is only spaces (no digit), then comma becomes space
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == ',' {
			// check if any placeholder to left has a digit printed (non-space)
			hasDigitLeft := false
			for j := 0; j < i; j++ {
				if intPic[j] == 'Z' || intPic[j] == '9' {
					if resultInt[j] != ' ' {
						hasDigitLeft = true
						break
					}
				}
			}
			if !hasDigitLeft {
				resultInt[i] = ' '
			} else {
				resultInt[i] = ','
			}
		}
	}
	intEdited := string(resultInt)
	if decPlaces > 0 {
		edited := intEdited + "." + fracPartStr
		if neg {
			// Not needed for this program
			edited = "-" + edited
		}
		// Ensure width equals pic length
		return edited
	}
	return intEdited
}

func truncateDecimal(val decimal.Decimal, scale int32) decimal.Decimal {
	return val.Truncate(scale)
}

func parseDecimalDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// digits only
	d := decimal.RequireFromString(s)
	// shift
	return decimal.New(d.IntPart(), -scale)
}

func readEmpRec() (EmpRec, bool) {
	line, err := empReader.ReadString('\n')
	if err != nil {
		// Check if we got partial line
		if len(line) == 0 {
			return EmpRec{}, true
		}
	}
	// Remove trailing \r and \n
	line = strings.TrimRight(line, "\r\n")
	if err != nil && len(line) == 0 {
		return EmpRec{}, true
	}
	// Pad to 17
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	}
	if len(line) > 17 {
		line = line[:17]
	}
	rec := EmpRec{}
	rec.ErId = line[0:5]
	rec.ErDept = line[5:8]
	rec.ErHours = parseDecimalDigits(line[8:12], 1)
	rec.ErRate = parseDecimalDigits(line[12:17], 2)
	return rec, false
}

func main() {
	var err error
	empFile, err = os.Open("input.dat")
	if err != nil {
		// If file doesn't exist, treat as empty
		empFile = nil
		empReader = bufio.NewReader(strings.NewReader(""))
	} else {
		empReader = bufio.NewReader(empFile)
		defer empFile.Close()
	}
	MAIN_PARA()
}

func MAIN_PARA() {
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	if WsFirstFlag != "Y" {
		DEPT_BREAK_PARA()
	}
	GRAND_PARA()
}

func READ_PARA() {
	if empFile == nil && empReader != nil {
		// already handled
	}
	rec, eof := readEmpRec()
	if eof {
		WsEofFlag = "Y"
		inputDone = true
	} else {
		EmpRecState = rec
	}
}

func PROCESS_PARA() {
	if WsFirstFlag == "Y" {
		WsPrevDept = EmpRecState.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecState.ErDept != WsPrevDept {
			DEPT_BREAK_PARA()
			WsPrevDept = EmpRecState.ErDept
		}
	}
	PAY_PARA()
	READ_PARA()
}

func PAY_PARA() {
	forty := decimal.NewFromInt(40)
	if EmpRecState.ErHours.GreaterThan(forty) {
		WsRegHours = decimal.NewFromInt(40)
		WsOtHours = EmpRecState.ErHours.Sub(decimal.NewFromInt(40))
		WsOtHours = truncateDecimal(WsOtHours, 1)
	} else {
		WsRegHours = EmpRecState.ErHours
		WsOtHours = decimal.NewFromInt(0)
	}
	// COMPUTE WS-GROSS ROUNDED = WS-REG-HOURS * ER-RATE + WS-OT-HOURS * ER-RATE * 1.5
	onePointFive := decimal.NewFromInt(15).Shift(-1) // 1.5
	val := WsRegHours.Mul(EmpRecState.ErRate).Add(WsOtHours.Mul(EmpRecState.ErRate).Mul(onePointFive))
	WsGross = val.Round(2)
	// Truncate to PIC 9(7)V99 scale 2 (low-order truncation not needed here)
	WsGross = truncateDecimal(WsGross, 2)

	WsDeptTotal = WsDeptTotal.Add(WsGross)
	WsDeptCount += 1
	WsGrandTotal = WsGrandTotal.Add(WsGross)
	WsGrandCount += 1

	WsHoursEd = formatNumericEdited(EmpRecState.ErHours, "ZZ9.9")
	WsRateEd = formatNumericEdited(EmpRecState.ErRate, "ZZ9.99")
	WsGrossEd = formatNumericEdited(WsGross, "Z,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", EmpRecState.ErId, EmpRecState.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DEPT_BREAK_PARA() {
	WsDeptEd = formatNumericEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	// WS-DEPT-COUNT is PIC 9(3) zero-padded by DISPLAY? In COBOL DISPLAY of numeric unedited prints as is? But this program displays WS-DEPT-COUNT as numeric field.
	// The declarations: WS-DEPT-COUNT PIC 9(3) . DISPLAY will show it without editing; COBOL displays numeric fields as digits, but without leading zeros? Actually unedited numeric DISPLAY shows the value without leading zeros? However spec says: PIC 9(n) prints zero-padded.
	// But COBOL typically displays PIC 9(3) as with leading zeros? Let's follow spec: zero-padded.
	// However COBOL's DISPLAY of PIC 9(3) may show without padding? Need to test expectation: spec in task says "An unedited numeric DISPLAY item such as PIC 9(5) prints zero-padded to its digit count."
	// So we must zero-pad to 3 digits.
	countStr := fmt.Sprintf("%03d", WsDeptCount)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, countStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GRAND_PARA() {
	WsGrandEd = formatNumericEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsGrandCount)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}

