	for idx, p := range placeholders {
		phIdxMap[p.picIdx] = idx
	}
	if firstNonZero == -1 {
		// all zeros: only rightmost prints 0
		lastIdx := placeholders[len(placeholders)-1].picIdx
		for _, p := range placeholders {
